import React, { forwardRef, useState } from 'react';
import { Stack, Container } from '@fiverr-private/layout_components';
import { Heading, Text } from '@fiverr-private/typography';
import { Button } from '@fiverr-private/button';
import { Input } from '@fiverr-private/forms';
import {
  Collapsible,
  CollapsibleHeader,
  CollapsibleContent,
  CollapsibleHeaderChevron,
} from '@fiverr-private/disclosure';
import useStepper from '..';
import type { StepperStep } from '../types';

interface Step extends StepperStep {
  stepId: number;
  Component: React.ComponentType<any>;
  label: string;
}

const Step1Content = forwardRef<HTMLElement, Step>((props, ref) => (
  <Stack padding="8" ref={ref} direction="column" {...props}>
    <Heading>Step 1</Heading>
    <Text>Step 1 content</Text>
  </Stack>
));

Step1Content.displayName = 'Step1Content';

const Step2Content = forwardRef<HTMLElement, Step>((props, ref) => (
  <Stack padding="8" ref={ref} direction="column" {...props}>
    <Heading>Step 2</Heading>
    <Text>Step 2 content</Text>
  </Stack>
));

Step2Content.displayName = 'Step2Content';

const Step3Content = forwardRef<HTMLElement, Step>((props, ref) => (
  <Stack padding="8" ref={ref} direction="column" {...props}>
    <Heading>Step 3</Heading>
    <Text>Step 3 content</Text>
  </Stack>
));

Step3Content.displayName = 'Step3Content';

const stepsData: Step[] = [
  { stepId: 1, Component: Step1Content, label: 'Step 1' },
  { stepId: 2, Component: Step2Content, label: 'Step 2' },
  { stepId: 3, Component: Step3Content, label: 'Step 3' },
];

export const UncontrolledStepper = () => {
  const { currentStep, hasPreviousStep, hasNextStep, nextStep, prevStep, stepsProps, stepperProps } = useStepper({
    steps: stepsData,
  });

  const CurrentStepComponent = stepsData[currentStep].Component;

  return (
    <Stack direction="column" justifyContent="center" alignItems="center">
      <Stack as="nav" {...stepperProps}>
        {stepsProps?.map(({ key, ...rest }, index) => (
          <Button key={key} variant={currentStep === index ? 'outline' : 'ghost'} {...rest}>
            {stepsData[index].label}
          </Button>
        ))}
      </Stack>
      <Container>
        <CurrentStepComponent {...stepsProps[currentStep]} />
      </Container>
      <Stack direction="row" padding="10">
        <Button onClick={prevStep} disabled={!hasPreviousStep}>
          Prev
        </Button>
        <Button onClick={nextStep} disabled={!hasNextStep}>
          Next
        </Button>
      </Stack>
    </Stack>
  );
};

export const ControlledStepper = () => {
  const [currentStep, setCurrentStep] = React.useState(1); // Control the current step from outside
  const { hasPreviousStep, hasNextStep, nextStep, prevStep, stepsProps, stepperProps } = useStepper({
    steps: stepsData,
    currentStep,
    onCurrentStepChanged: setCurrentStep,
  });

  const CurrentStepComponent = stepsData[currentStep].Component;

  return (
    <Stack direction="column" justifyContent="center" alignItems="center">
      <Stack as="nav" {...stepperProps}>
        {stepsProps?.map(({ key, ...rest }, index) => (
          <Button key={key} variant={currentStep === index ? 'outline' : 'ghost'} {...rest}>
            {stepsData[index].label}
          </Button>
        ))}
      </Stack>
      <Container>
        <CurrentStepComponent {...stepsProps[currentStep]} />
      </Container>
      <Stack direction="row" padding="10">
        <Button onClick={prevStep} disabled={!hasPreviousStep}>
          Prev
        </Button>
        <Button onClick={nextStep} disabled={!hasNextStep}>
          Next
        </Button>
      </Stack>
    </Stack>
  );
};

